    .is-validity{display:grid;grid-template-columns:minmax(210px,.65fr) minmax(0,1.35fr);gap:1rem;margin-top:1rem}.is-field{padding:1rem;border:1px solid #e8ebef;border-radius:15px}.is-field-label{font-weight:800;color:#303743;font-size:.88rem}.is-field-copy{color:var(--is-muted);font-size:.78rem;margin:.2rem 0 .75rem}.is-days{display:flex;gap:.5rem;flex-wrap:wrap}.is-day input{position:absolute;opacity:0;pointer-events:none}.is-day span{display:inline-flex;align-items:center;justify-content:center;min-width:76px;padding:.55rem .7rem;border:1px solid #dfe3e8;border-radius:10px;background:#fff;color:#515966;font-size:.84rem;font-weight:700;cursor:pointer}.is-day input:checked+span{color:#9d4b00;border-color:#f0b77f;background:#fff0e1;box-shadow:inset 0 0 0 1px #f3c393}
