    @media(max-width:900px){.is-toggle-grid,.is-cert-grid,.is-validity{grid-template-columns:1fr}.is-notification{grid-template-columns:1fr;gap:.55rem}.is-aging-grid,.is-sign-grid{grid-template-columns:1fr}.is-upload{grid-column:auto}}
