  <header class="is-hero"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><h1 class="is-title mb-2">Barangay Issuance Settings</h1><p class="is-lead mb-0">Manage certificate availability, validity, verification, resident messages, request choices, and signatory details from one page.</p><div class="is-summary"><span class="is-summary-chip"><i class="fa-solid fa-file-circle-check"></i><?= count(dms_issuance_certificate_catalog()) ?> certificates</span><span class="is-summary-chip"><i class="fa-solid fa-calendar-check"></i><?= (int)$issuanceSettings['default_validity_days'] ?>-day default</span><span class="is-summary-chip"><i class="fa-solid fa-bell"></i>5 resident events</span></div></div><div class="is-hero-actions"><a class="btn btn-outline-secondary" href="<?= htmlspecialchars($documentSettingsBackUrl) ?>"><i class="fa-solid fa-arrow-left me-2"></i>Back to Module</a></div></div></header>
  <?php if ($documentSettingsSuccessMessage !== ''): ?><div class="alert alert-success mt-3 mb-0"><i class="fa-solid fa-circle-check me-2"></i><?= htmlspecialchars($documentSettingsSuccessMessage) ?></div><?php endif; ?>
  <?php if ($documentSettingsErrorMessage !== ''): ?><div class="alert alert-danger mt-3 mb-0"><i class="fa-solid fa-triangle-exclamation me-2"></i><?= htmlspecialchars($documentSettingsErrorMessage) ?></div><?php endif; ?>
  <form method="post" action="<?= htmlspecialchars($documentSettingsActionUrl) ?>" id="issuanceSettingsForm"><?= csrfTokenField() ?><input type="hidden" name="action" value="save_issuance_settings">
    <section class="is-section" id="general"><div class="is-section-head"><span class="is-section-icon"><i class="fa-solid fa-sliders"></i></span><div><h2 class="is-section-title">General issuance controls</h2><p class="is-section-copy">Set the rules applied across online certificate requests and document generation.</p></div></div><div class="is-section-body">
      <div class="is-toggle-grid">
        <?php $toggles=[['online_requests_enabled','Online certificate requests','Allow residents to submit certificate applications online.'],['first_time_job_seeker_exempt','First-Time Job Seeker exemption','Automatically treat eligible first-time job seeker requests as fee-exempt.'],['qr_verification_enabled','QR verification','Add verification details to supported generated certificates.'],['essential_details_only','Essential resident details only','Limit certificate views to information needed for processing.']]; foreach($toggles as [$key,$title,$copy]): ?><label class="is-toggle" for="<?= $key ?>"><input class="form-check-input" type="checkbox" name="<?= $key ?>" id="<?= $key ?>" <?= !empty($issuanceSettings[$key])?'checked':'' ?>><span><span class="is-toggle-title"><?= htmlspecialchars($title) ?></span><span class="is-toggle-copy"><?= htmlspecialchars($copy) ?></span></span></label><?php endforeach; ?>
      </div>
      <div class="is-validity"><div class="is-field"><label class="is-field-label" for="default_validity_days">Default validity</label><p class="is-field-copy">Used when staff do not choose another period.</p><div class="input-group"><input class="form-control" id="default_validity_days" type="number" min="1" max="365" name="default_validity_days" value="<?= (int)$issuanceSettings['default_validity_days'] ?>"><span class="input-group-text">days</span></div></div><div class="is-field"><div class="is-field-label">Allowed validity choices</div><p class="is-field-copy">Choose the periods staff can select during approval and manual issuance.</p><div class="is-days"><?php foreach([3,7,15,30,45,60,90,180,365] as $days): ?><label class="is-day"><input type="checkbox" name="allowed_validity_days[]" value="<?= $days ?>" <?= in_array($days,(array)$issuanceSettings['allowed_validity_days'],true)?'checked':'' ?>><span><?= $days ?> days</span></label><?php endforeach; ?></div></div></div>
    </div></section>

    <section class="is-section" id="certificates"><div class="is-section-head"><span class="is-section-icon"><i class="fa-solid fa-file-lines"></i></span><div><h2 class="is-section-title">Certificates and request choices</h2><p class="is-section-copy">Control availability and customize the purpose dropdown for every supported certificate.</p></div></div><div class="is-section-body"><div class="is-cert-grid">
      <?php foreach(dms_issuance_certificate_catalog() as $key=>$label): $cert=$issuanceSettings['certificates'][$key]??[]; ?><article class="is-cert"><div class="is-cert-top"><span class="is-cert-name"><?= htmlspecialchars($label) ?></span><div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" name="certificate_enabled[<?= $key ?>]" id="cert_<?= $key ?>" <?= !empty($cert['enabled'])?'checked':'' ?> aria-label="Enable <?= htmlspecialchars($label) ?>"></div></div><div class="is-cert-body"><label class="form-label small fw-bold" for="options_<?= $key ?>">Purpose dropdown options</label><p class="small text-muted mb-2">One option per line. Include “Other” to allow a custom answer.</p><textarea class="form-control is-options" id="options_<?= $key ?>" name="purpose_options[<?= $key ?>]"><?= htmlspecialchars(implode("\n",(array)($cert['purpose_options']??[]))) ?></textarea></div></article><?php endforeach; ?>
    </div></div></section>

    <section class="is-section" id="notifications"><div class="is-section-head"><span class="is-section-icon"><i class="fa-solid fa-bell"></i></span><div><h2 class="is-section-title">Notifications</h2><p class="is-section-copy">Choose which status updates residents receive and customize the message for each event.</p></div></div><div class="is-section-body"><div class="is-placeholder"><code>{request_id}</code><code>{document_type}</code><code>{reason}</code><code>{count}</code><code>{days}</code></div>
      <?php foreach((array)$issuanceSettings['resident_notifications'] as $event=>$notification): ?><div class="is-notification"><div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="notification_enabled[<?= htmlspecialchars($event) ?>]" id="notify_<?= htmlspecialchars($event) ?>" <?= !empty($notification['enabled'])?'checked':'' ?>><label class="form-check-label fw-bold text-capitalize" for="notify_<?= htmlspecialchars($event) ?>"><?= htmlspecialchars(str_replace('_',' ',$event)) ?></label></div><div class="small text-muted mt-1">Resident status update</div></div><textarea class="form-control is-message" name="notification_message[<?= htmlspecialchars($event) ?>]" maxlength="500" aria-label="<?= htmlspecialchars(str_replace('_',' ',$event)) ?> message"><?= htmlspecialchars((string)$notification['message']) ?></textarea></div><?php endforeach; ?>
      <div class="is-aging"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="aging_notification_enabled" id="aging_notification_enabled" <?= !empty($issuanceSettings['aging_notification_enabled'])?'checked':'' ?>><label class="form-check-label fw-bold" for="aging_notification_enabled">Admin notification for aging requests</label></div><p class="small text-muted mb-0 mt-1">Alert administrators when certificate requests remain pending beyond the threshold.</p><div class="is-aging-grid"><div><label class="form-label small fw-bold" for="aging_days">Threshold</label><div class="input-group"><input class="form-control" id="aging_days" type="number" min="1" max="90" name="aging_days" value="<?= (int)$issuanceSettings['aging_days'] ?>"><span class="input-group-text">days</span></div></div><div><label class="form-label small fw-bold" for="aging_message">Admin message</label><textarea class="form-control" id="aging_message" name="aging_message" rows="2"><?= htmlspecialchars((string)$issuanceSettings['aging_message']) ?></textarea></div></div></div>
    </div></section>

    <div class="is-savebar mb-3"><span class="is-save-note"><i class="fa-solid fa-shield-halved me-2 text-success"></i>Changes are audit logged and apply after saving.</span><button class="btn btn-is-primary px-4" type="submit"><i class="fa-solid fa-floppy-disk me-2"></i>Save Issuance Settings</button></div>
  </form>

  <section class="is-section" id="signatory"><div class="is-section-head"><span class="is-section-icon"><i class="fa-solid fa-signature"></i></span><div><h2 class="is-section-title">Certificate signatory</h2><p class="is-section-copy">The seated official’s identity is synchronized automatically. Upload the signature asset used on generated certificates.</p></div></div><form class="is-section-body" method="post" enctype="multipart/form-data" action="<?= htmlspecialchars($documentSettingsActionUrl) ?>"><?= csrfTokenField() ?><input type="hidden" name="action" value="save_document_module_settings">
    <?php foreach($documentSettingsRows as $row): $key=(string)$row['signatory_key']; ?><div class="is-sign-grid"><div><label class="form-label fw-bold">Signatory name</label><input class="form-control" name="signatory_name_<?= $key ?>" value="<?= htmlspecialchars((string)$row['name']) ?>" <?= $row['source']==='manual'?'':'readonly' ?>></div><div><label class="form-label fw-bold">Official title</label><input class="form-control" name="signatory_title_<?= $key ?>" value="<?= htmlspecialchars((string)$row['title']) ?>" <?= $row['source']==='manual'?'':'readonly' ?>></div><div class="is-upload"><label class="form-label fw-bold">Signature image</label><input class="form-control" type="file" accept="image/png,image/jpeg,image/webp" name="signature_file_<?= $key ?>"><div class="form-text">PNG with a transparent background is recommended.</div></div></div><?php endforeach; ?><div class="text-end mt-3"><button class="btn btn-is-primary px-4"><i class="fa-solid fa-signature me-2"></i>Save Signatory</button></div>
  </form></section>
</div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script></body></html>
